def extract_title(obj):
    p=obj.get("properties") or {}
    for v in p.values():
        if isinstance(v,dict) and v.get("type")=="title":
            t=v.get("title") or []
            return "".join(x.get("plain_text","") for x in t if isinstance(x,dict)).strip()
    return ""
